styles:
.page-case .case-eyebrow { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: clamp(18px, 3vw, 30px); }
.page-case .case-tag {
  font-size: 13px; color: var(--red); line-height: 1;
  border: 1px solid #f2c9c9; background: #fff5f5;
  border-radius: 999px; padding: 6px 12px; letter-spacing: .01em;
}
.page-case .case-meta {
  display: flex; flex-wrap: wrap; gap: 12px 26px;
  margin-top: clamp(20px, 3vw, 34px);
  color: var(--grey-500); font-size: clamp(14px, 1.05vw, 17px);
}
.page-case .case-meta span { display: inline-flex; align-items: center; gap: 8px; }
.page-case .case-meta svg { width: 16px; height: 16px; color: var(--red); flex-shrink: 0; }

.page-case .case-cover {
  border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt);
  margin-top: clamp(30px, 5vw, 60px);
}
.page-case .case-cover img { width: 100%; height: auto; display: block; }

.page-case .case-intro { max-width: 68ch; }
.page-case .case-intro .lead {
  font-family: var(--font-display); font-size: clamp(22px, 2.4vw, 36px);
  color: var(--grey-900); line-height: 1.18;
}

.page-case .case-block { display: grid; grid-template-columns: 1fr 1.6fr; gap: clamp(20px, 4vw, 70px); align-items: start; padding-block: clamp(30px, 4vw, 56px); border-bottom: 1px solid var(--line); }
.page-case .case-block:first-of-type { border-top: 1px solid var(--line); }
.page-case .case-block h2 { font-size: clamp(26px, 3.2vw, 46px); color: var(--grey-900); }
.page-case .case-block p { color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); }
.page-case .case-block p + p { margin-top: 16px; }

.page-case .case-steps { list-style: none; display: grid; gap: 22px; }
.page-case .case-steps li { display: grid; grid-template-columns: auto 1fr; gap: 16px; align-items: start; }
.page-case .case-steps .num {
  font-family: var(--font-display); font-size: clamp(20px, 2vw, 28px);
  color: var(--red); line-height: 1; min-width: 1.6em;
}
.page-case .case-steps .step-t { font-family: var(--font-display); font-size: clamp(18px, 1.5vw, 22px); color: var(--grey-900); display: block; margin-bottom: 4px; }
.page-case .case-steps .step-b { color: var(--grey-700); font-size: clamp(15px, 1.1vw, 18px); }

.page-case .case-gallery { display: grid; grid-template-columns: repeat(2, 1fr); gap: clamp(16px, 2vw, 28px); }
.page-case .case-gallery figure { margin: 0; border-radius: var(--radius); overflow: hidden; background: var(--bg-alt); }
.page-case .case-gallery img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform .8s var(--ease); }
.page-case .case-gallery figure:hover img { transform: scale(1.04); }

.page-case .case-back { margin-top: clamp(30px, 4vw, 52px); }

@media (max-width: 820px) {
  .page-case .case-block { grid-template-columns: 1fr; gap: 14px; }
  .page-case .case-gallery { grid-template-columns: 1fr; }
}
